function COMPOSE_EXPONENTS(forward[1..n], inverse[1..n]):
    fwd <- 1 ; inv <- 1
    for i in 1..n: fwd <- fwd * forward[i]
    for i in 1..n: inv <- inv * inverse[i]
    return (fwd, inv)

function DIMENSION_WINDOW(dim_source, fwd, inv):
    return (dim_source * inv, dim_source / fwd)

