if __name__ == '__main__':
    base = [1/3, 1/3]
    d0 = similarity_dimension(base)
    print('Cantor dimension       :', round(d0, 6))
    rf, rg = 0.5, 2/3
    once = similarity_dimension([c**rf for c in base])
    twice = similarity_dimension([(c**rf)**rg for c in base])
    print('after snowflake rf=1/2 :', round(once, 6),
